import { sql } from "drizzle-orm";
import {
  index,
  integer,
  pgEnum,
  pgTable,
  text,
  timestamp,
} from "drizzle-orm/pg-core";
import { organization, user } from "./auth-schema";

// Better Auth tables (generated by `npm run auth:generate` — don't edit that file)
export * from "./auth-schema";

// ---------- locations ----------
export const locations = pgTable(
  "locations",
  {
    id: text().primaryKey().$defaultFn(() => crypto.randomUUID()),
    organizationId: text()
      .notNull()
      .references(() => organization.id, { onDelete: "cascade" }),
    name: text().notNull(),
    timezone: text(), // null = use organization.timezone
    address: text(),
    createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp({ withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [index().on(t.organizationId)],
);

// ---------- access_requests ----------
export const accessRequestStatus = pgEnum("access_request_status", [
  "pending",
  "approved",
  "rejected",
]);

// Platform-level: no tenant yet, so organizationId is optional.
// Only /admin reads this table.
export const accessRequests = pgTable(
  "access_requests",
  {
    id: text().primaryKey().$defaultFn(() => crypto.randomUUID()),

    // who's asking
    name: text().notNull(),
    email: text().notNull(),
    company: text().notNull(),
    industry: text().notNull(),
    locationCount: integer(),
    systems: text().array().notNull().default(sql`'{}'::text[]`),
    message: text(),

    // review
    status: accessRequestStatus().notNull().default("pending"),
    reviewedBy: text().references(() => user.id, { onDelete: "set null" }),
    reviewedAt: timestamp({ withTimezone: true }),
    organizationId: text().references(() => organization.id, {
      onDelete: "set null",
    }),

    createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index().on(t.status)],
);
